#include <string>
#include <vector>

std::vector<std::string> checkPath(int startIrql, const std::vector<std::string>& ops)
{
    std::vector<std::string> problems;
    std::vector<int> saved;                                     // IRQLs to restore, one per held spin lock
    int irql{ startIrql };
    for (std::size_t i{ 0 }; i < ops.size(); ++i)
    {
        const std::string& op{ ops[i] };
        bool allowed{ true };
        if (op == "acquire_spinlock") allowed = irql <= 2;
        else if (op == "release_spinlock") allowed = !saved.empty();
        else if (op == "wait" || op == "touch_paged" || op == "call_pageable") allowed = irql < 2;
        if (!allowed) problems.push_back("step " + std::to_string(i + 1) + ": " + op + " at IRQL " + std::to_string(irql));

        if (op == "acquire_spinlock") { saved.push_back(irql); irql = 2; }
        else if (op == "release_spinlock" && !saved.empty()) { irql = saved.back(); saved.pop_back(); }
    }
    if (!saved.empty()) problems.push_back("end: " + std::to_string(saved.size()) + " spin lock(s) still held");
    return problems;
}

unitTests:
using P = std::vector<std::string>;
TEST("a correct path") { CHECK(checkPath(0, { "touch_paged", "acquire_spinlock", "touch_nonpaged", "release_spinlock", "wait" }).empty()); }
TEST("waiting while holding a spin lock") { CHECK(checkPath(0, { "acquire_spinlock", "wait", "release_spinlock" }) == P({ "step 2: wait at IRQL 2" })); }
TEST("paged memory in a DPC") { CHECK(checkPath(2, { "touch_nonpaged", "touch_paged" }) == P({ "step 2: touch_paged at IRQL 2" })); }
TEST("release restores the previous level") { CHECK(checkPath(1, { "acquire_spinlock", "release_spinlock", "wait" }).empty()); }
TEST("nested locks") { CHECK(checkPath(0, { "acquire_spinlock", "acquire_spinlock", "release_spinlock", "call_pageable", "release_spinlock", "call_pageable" }) == P({ "step 4: call_pageable at IRQL 2" })); }
TEST("release without acquire") { CHECK(checkPath(0, { "release_spinlock" }) == P({ "step 1: release_spinlock at IRQL 0" })); }
TEST("a lock left held") { CHECK(checkPath(0, { "acquire_spinlock" }) == P({ "end: 1 spin lock(s) still held" })); }
TEST("acquiring above DISPATCH_LEVEL") { CHECK(checkPath(5, { "acquire_spinlock", "release_spinlock" }) == P({ "step 1: acquire_spinlock at IRQL 5" })); }

